#ifndef TIMER_H_
#define TIMER_H_

#include <stdint.h>
#include <stdbool.h>

/* Khởi tạo Timer0 (1 kHz CTC) và Timer2 (50 kHz CTC) */
void timer_init(void);

/* Trả về số ms hệ thống từ khi khởi động */
uint32_t timer_get_ms(void);

/* Kiểm tra và xoá cờ chu kỳ vòng cân bằng 4 ms (Tầng 2) */
bool timer_check_control_flag(void);

#endif /* TIMER_H_ */

#ifndef TIMER_H_
#define TIMER_H_

#include <stdint.h>
#include <stdbool.h>

/* Khởi tạo Timer0 (1 kHz CTC) và Timer2 (50 kHz CTC) */
void timer_init(void);

/* Trả về số ms hệ thống từ khi khởi động */
uint32_t timer_get_ms(void);

/* Kiểm tra và xoá cờ chu kỳ vòng cân bằng 4 ms (Tầng 2) */
bool timer_check_control_flag(void);

#endif /* TIMER_H_ */

#include "timer.h"
#include "config.h"
#include <avr/interrupt.h>

static volatile uint32_t s_system_ms = 0;
static volatile bool s_flag_control_4ms = false;
static volatile uint8_t s_tick_counter_4ms = 0;

/* Khai báo hàm ngắt tầng 1 sinh xung bước từ mô-đun motor */
extern void motor_isr_step(void);

void timer_init(void) {
    /* -------------------------------------------------------------------------
     * Cấu hình Timer0: Chế độ CTC, Prescaler 64
     * 16 MHz / 64 = 250 kHz -> OCR0A = 249 tạo ngắt chu kỳ đúng 1 ms (1000 Hz)
     * (anh cho, chưa có tài liệu)
     * ------------------------------------------------------------------------- */
    TCCR0A = (1 << WGM01);              /* CTC mode */
    TCCR0B = (1 << CS01) | (1 << CS00); /* Prescaler 64 */
    OCR0A  = 249;
    TIMSK0 |= (1 << OCIE0A);            /* Bật ngắt so sánh kênh A */

    /* -------------------------------------------------------------------------
     * Cấu hình Timer2: Chế độ CTC, Prescaler 8
     * 16 MHz / 8 = 2 MHz -> OCR2A = 39 tạo ngắt chu kỳ đúng 20 µs (50000 Hz)
     * (anh cho, chưa có tài liệu)
     * ------------------------------------------------------------------------- */
    TCCR2A = (1 << WGM21);              /* CTC mode */
    TCCR2B = (1 << CS21);               /* Prescaler 8 */
    OCR2A  = 39;
    TIMSK2 |= (1 << OCIE2A);            /* Bật ngắt so sánh kênh A */
}

/* Ngắt Timer0: 1 ms hệ thống, đánh cờ kích hoạt Tầng 2 mỗi 4 ms */
ISR(TIMER0_COMPA_vect) {
    s_system_ms++;
    s_tick_counter_4ms++;
    if (s_tick_counter_4ms >= CONTROL_LOOP_MS) {
        s_tick_counter_4ms = 0;
        s_flag_control_4ms = true;
    }
}

/* Ngắt Timer2: Tầng 1 sinh xung bước (50 kHz, chu kỳ 20 µs) */
ISR(TIMER2_COMPA_vect) {
    motor_isr_step();
}

uint32_t timer_get_ms(void) {
    uint32_t ms;
    uint8_t sreg = SREG;
    cli(); /* Cấm ngắt ngắn gọn (< 0.5 µs, tuân thủ NFR-02) */
    ms = s_system_ms;
    SREG = sreg;
    return ms;
}

bool timer_check_control_flag(void) {
    if (s_flag_control_4ms) {
        s_flag_control_4ms = false;
        return true;
    }
    return false;
}

