#include "config.h"
#include "timer.h"
#include "i2c.h"
#include "mpu6050.h"
#include "motor.h"
#include "fsm.h"
#include <avr/interrupt.h>

int main(void) {
    /* 1. Khởi tạo giao tiếp I2C phần cứng TWI */
    i2c_init();

    /* 2. Khởi tạo cảm biến con quay quán tính MPU6050 */
    mpu6050_init();

    /* 3. Khởi tạo chân I/O điều khiển động cơ bước A4988 */
    motor_init();

    /* 4. Khởi tạo máy trạng thái và chân nút nhấn/còi */
    fsm_init();

    /* 5. Khởi tạo hệ thống Timer0 (1 kHz) và Timer2 (50 kHz) */
    timer_init();

    /* 6. Cho phép ngắt toàn cục */
    sei();

    /* Vòng lặp chính kết hợp Tầng 2 và Tầng 3 */
    while (1) {
        /* Tầng 2: Vòng lặp điều khiển thời gian thực chu kỳ 4 ms (250 Hz) */
        if (timer_check_control_flag()) {
            fsm_update_control_4ms();
        }

        /* Tầng 3: Tác vụ nền phi chặn (nút bấm, còi, kiểm tra trạng thái) */
        fsm_update_background();

        /* LƯU Ý BẢO MẬT THỜI GIAN THỰC (NFR-02):
         * - Không sử dụng _delay_ms() gây chặn CPU.
         * - Tuyệt đối không cấm ngắt quá 1,5 µs.
         * - Không truyền chuỗi LED WS2812 khi hệ thống đang vận hành cân bằng.
         */
    }

    return 0;
}

